<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';
$error=null;$success=null;$permissions=[];$matrix=[];$users=[];$overrides=[];
try{
    $pdo=business_db();security_step17_ensure($pdo);$actor=security_step17_current_user($pdo);$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();
    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
        if($action==='role'){$role=(string)($_POST['role_code']??'');$permission=(string)($_POST['permission_code']??'');$allowed=(string)($_POST['allowed']??'0')==='1';security_step17_set_role_permission($pdo,$role,$permission,$allowed);$success='Role permission updated. Active sessions for '.strtoupper($role).' were revoked so the new policy applies on next sign-in.';}
        elseif($action==='override'){$uid=(int)($_POST['user_id']??0);$permission=(string)($_POST['permission_code']??'');$mode=(string)($_POST['override_mode']??'inherit');$allowed=$mode==='inherit'?null:($mode==='allow');security_step17_set_user_override($pdo,$uid,$permission,$allowed);$success='User-specific permission override updated. Active sessions for that user were revoked.';}
    }
    $permissions=$pdo->query("SELECT * FROM security_permissions WHERE is_active=1 ORDER BY module_code,permission_code")->fetchAll();
    $stmt=$pdo->prepare("SELECT role_code,permission_code,is_allowed FROM security_role_permissions WHERE organization_id=?");$stmt->execute([$orgId]);foreach($stmt->fetchAll() as $r)$matrix[(string)$r['role_code']][(string)$r['permission_code']]=(int)$r['is_allowed']===1;
    $users=security_step17_users($pdo,$orgId);
    $stmt=$pdo->prepare("SELECT user_id,permission_code,is_allowed FROM security_user_permissions WHERE organization_id=?");$stmt->execute([$orgId]);foreach($stmt->fetchAll() as $r)$overrides[(int)$r['user_id']][(string)$r['permission_code']]=(int)$r['is_allowed']===1;
}catch(Throwable $e){$error=$e->getMessage();$csrf=$csrf??'';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Permission Matrix - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>.perm-grid{display:grid;grid-template-columns:minmax(260px,1.8fr) repeat(4,minmax(110px,.7fr));gap:1px;background:#dce8df;border:1px solid #dce8df;border-radius:16px;overflow:hidden}.perm-grid>div{background:#fff;padding:10px}.perm-head{font-weight:900;background:#f2f8f4!important}.perm-code{font-size:12px;color:#718078}.toggle-form{display:flex;gap:6px;align-items:center}.toggle-form button{border:1px solid #cfded3;border-radius:9px;padding:6px 9px;background:#fff;cursor:pointer}.toggle-form .on{background:#e7f6eb;color:#176c3a;border-color:#bfe1c9}.toggle-form .off{background:#fff1f1;color:#9d3333;border-color:#eccaca}.module-title{grid-column:1/-1;background:#edf7f0!important;font-weight:900;color:#236d43}</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="security_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 17 • Role & Permission Matrix</small></span></a><div class="os-top-actions"><a class="os-btn" href="user_management.php">Users</a><a class="os-btn primary" href="security_center.php">Security</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Security</div><nav class="os-nav"><a href="security_center.php"><i class="dot"></i>Security Center</a><a href="user_management.php"><i class="dot"></i>Users</a><a class="active" href="permission_matrix.php"><i class="dot"></i>Permissions</a><a href="security_sessions.php"><i class="dot"></i>Sessions</a><a href="security_audit.php"><i class="dot"></i>Audit</a></nav><div class="os-sidebar-status"><b>Administrator</b><span>Admin full-access is immutable. Only Manager, Staff and Viewer defaults can be changed.</span></div></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">RBAC • MODULE-WISE ACCESS</div><h1>Control what each role can view and manage.</h1><p>Role permissions are the default. A user-specific override can explicitly Allow or Deny one permission without changing everyone in that role.</p></section><?php if($error):?><div class="pp-alert bad"><strong>Permissions:</strong> <?= security_step17_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= security_step17_h($success) ?></div><?php endif;?><section class="os-card"><div class="perm-grid"><div class="perm-head">Permission</div><div class="perm-head">ADMIN</div><div class="perm-head">MANAGER</div><div class="perm-head">STAFF</div><div class="perm-head">VIEWER</div><?php $lastModule='';foreach($permissions as $p):$module=(string)$p['module_code'];if($module!==$lastModule):$lastModule=$module;?><div class="module-title"><?= security_step17_h(strtoupper($module)) ?></div><?php endif;?><div><b><?= security_step17_h($p['permission_name']) ?></b><div class="perm-code"><?= security_step17_h($p['permission_code'].' • '.$p['risk_level']) ?></div><small><?= security_step17_h($p['description']??'') ?></small></div><div><span class="pp-badge">ALWAYS ON</span></div><?php foreach(['manager','staff','viewer'] as $role):$on=!empty($matrix[$role][$p['permission_code']]);?><div><form method="post" class="toggle-form"><input type="hidden" name="csrf" value="<?= security_step17_h($csrf) ?>"><input type="hidden" name="action" value="role"><input type="hidden" name="role_code" value="<?= $role ?>"><input type="hidden" name="permission_code" value="<?= security_step17_h($p['permission_code']) ?>"><input type="hidden" name="allowed" value="<?= $on?'0':'1' ?>"><button class="<?= $on?'on':'off' ?>"><?= $on?'✓ ALLOW':'✕ DENY' ?></button></form></div><?php endforeach;?><?php endforeach;?></div></section><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>User-specific Override</h2><p>Use sparingly. Inherit follows the role matrix; Allow/Deny overrides that one permission.</p></div></div><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= security_step17_h($csrf) ?>"><input type="hidden" name="action" value="override"><label>User<select name="user_id" required><?php foreach($users as $u):if($u['role_code']==='admin')continue;?><option value="<?= (int)$u['id'] ?>"><?= security_step17_h($u['full_name'].' • '.strtoupper((string)$u['role_code']).' • '.$u['email']) ?></option><?php endforeach;?></select></label><label>Permission<select name="permission_code" required><?php foreach($permissions as $p):?><option value="<?= security_step17_h($p['permission_code']) ?>"><?= security_step17_h($p['permission_name'].' • '.$p['permission_code']) ?></option><?php endforeach;?></select></label><label>Override<select name="override_mode"><option value="inherit">Inherit role</option><option value="allow">Explicit Allow</option><option value="deny">Explicit Deny</option></select></label><button>Save User Override</button></form><?php $has=false;foreach($users as $u){$uid=(int)$u['id'];if(empty($overrides[$uid]))continue;$has=true;?><div class="pp-source"><b><?= security_step17_h($u['full_name']) ?></b><span><?php foreach($overrides[$uid] as $code=>$allowed):?><span class="pp-badge <?= $allowed?'':'warn' ?>"><?= security_step17_h($code) ?>: <?= $allowed?'ALLOW':'DENY' ?></span> <?php endforeach;?></span></div><?php }if(!$has):?><p>No user-specific overrides. All users currently inherit their role.</p><?php endif;?></section><div class="os-footer-note"><strong>Immediate enforcement:</strong> changing a role or user permission revokes affected active sessions. The user must sign in again under the new policy.</div></main></div></body></html>